import unittest
from candidate import largest_prime_factor

class TestLargestPrimeFactor(unittest.TestCase):
    def test_largest_prime_factor_normalcase(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_largest_prime_factor_power_of_two(self):
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_largest_prime_factor_small_composite(self):
        self.assertEqual(largest_prime_factor(100), 5)

    def test_largest_prime_factor_square_of_prime(self):
        self.assertEqual(largest_prime_factor(49), 7)

    def test_largest_prime_factor_prime_input(self):
        self.assertEqual(largest_prime_factor(17), 1)

    def test_largest_prime_factor_one(self):
        self.assertEqual(largest_prime_factor(1), 1)

    def test_largest_prime_factor_zero(self):
        self.assertEqual(largest_prime_factor(0), 1)

    def test_largest_prime_factor_negative(self):
        self.assertEqual(largest_prime_factor(-10), 1)

    def test_largest_prime_factor_return_type(self):
        self.assertIsInstance(largest_prime_factor(12345), int)

    def test_largest_prime_factor_repeated_calls(self):
        self.assertEqual(largest_prime_factor(2048), 2)
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_largest_prime_factor_large_number(self):
        self.assertEqual(largest_prime_factor(13195 * 13), 29)

    def test_largest_prime_factor_invalid_type_string(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("100")

    def test_largest_prime_factor_invalid_type_float(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(100.5)

    def test_largest_prime_factor_input_is_none(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(None)

    def test_largest_prime_factor_non_integer_numeric_string(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("1e3")

    def test_largest_prime_factor_boundary_large_composite(self):
        # 2 * 3 * 5 * 7 * 11 * 13 = 30030
        self.assertEqual(largest_prime_factor(30030), 13)

    def test_largest_prime_factor_boundary_small_composite(self):
        self.assertEqual(largest_prime_factor(2 * 3), 3)

    def test_largest_prime_factor_input_not_modified(self):
        n = 13195
        largest_prime_factor(n)
        self.assertEqual(n, 13195)

    def test_largest_prime_factor_is_prime_in_loop(self):
        # Ensure that is_prime works correctly by checking that 29 is found
        self.assertIn(29, [j for j in range(2, 13196) if 13195 % j == 0 and (lambda k: all(k % i != 0 for i in range(2, k))) (j)])

    def test_largest_prime_factor_non_integer_iterable(self):
        with self.assertRaises(TypeError):
            largest_prime_factor([100])

    def test_largest_prime_factor_tuple_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor((100,))

    def test_largest_prime_factor_string_of_digits(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("100")

    def test_largest_prime_factor_boolean_input(self):
        # bool is subclass of int; True == 1, False == 0
        self.assertEqual(largest_prime_factor(True), 1)
        self.assertEqual(largest_prime_factor(False), 1)

    def test_largest_prime_factor_float_as_integer(self):
        # float that is an integer value
        self.assertEqual(largest_prime_factor(10.0), 5)

    def test_largest_prime_factor_large_prime_factor(self):
        # 10^5 + 7 = 100007, whose largest prime factor is 100007 itself (prime)
        self.assertEqual(largest_prime_factor(100007), 1)

if __name__ == "__main__":
    unittest.main()
